function navigate(id){if(!all.some(x=>x[0]===id))id='welcome';clearInterval(holdTimer);clearTimeout(reportLoadTimer);route=id;if(['carbs','fats','protein'].includes(id))state.group=id;history.replaceState(null,'','#'+id);render();}
function next(){const idx=onboarding.findIndex(x=>x[0]===route);navigate(onboarding[idx+1]?.[0]||'kitchen')}
function primary(text,act='next',more=''){return `<button class="primary" data-action="${act}" ${more}>${text}${icon('arrow')}</button>`}
function choice(title,detail,key,value,ic='leaf'){return `<button class="choice ${state[key]===value?'selected':''}" data-choice="${key}" data-value="${value}" aria-pressed="${state[key]===value}"><span class="icon-wrap">${icon(ic)}</span><span class="label">${title}<small>${detail}</small></span><span class="check">${state[key]===value?'✓':''}</span></button>`}
