function plate(group=state.group,mini=false){const ids=state.selections[group];return `<div class="plate-wrap"><div class="plate" id="${mini?'mini-':'live-'}plate" data-group="${group}">${tokens(group)}<span class="plate-label">${group.toUpperCase()}</span>${ids.length?'':`<div class="plate-empty">${icon('plate')}Your plate is ready.<br>Add your first app.</div>`}</div></div>`}
function positions(n){
 if(n===1)return [[0,-7]];
 if(n<=4)return Array.from({length:n},(_,i)=>{let a=-Math.PI/2+i*2*Math.PI/n;return [Math.cos(a)*45,Math.sin(a)*45-5]});
 if(n<=8)return Array.from({length:n},(_,i)=>{let a=-Math.PI/2+i*2*Math.PI/n;return [Math.cos(a)*66,Math.sin(a)*66-4]});
 const inner=n-8;
 return Array.from({length:n},(_,i)=>{if(i<inner){if(inner===1)return [0,-4];let a=-Math.PI/4+i*2*Math.PI/inner;return [Math.cos(a)*31,Math.sin(a)*31-4]}let a=-Math.PI/2+(i-inner)*2*Math.PI/8;return [Math.cos(a)*77,Math.sin(a)*77-4]});
}
function tokens(g,newId){const ids=state.selections[g],pos=positions(ids.length);return ids.map((id,i)=>{let a=apps.find(x=>x.id===id);return `<button class="app-token ${id===newId?'land':''}" data-remove="${id}" title="Remove ${a.name}" aria-label="Remove ${a.name} from ${g}" style="--app-color:${a.color};--x:${pos[i][0]}px;--y:${pos[i][1]}px">${appLogo(a)}</button>`}).join('')}
function ring(value='32',label='min left',offset=65){return `<div class="ring" style="--offset:${offset}"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="35" stroke="#bdcd9417"/><circle class="progress-ring" cx="40" cy="40" r="35"/></svg><div class="number"><strong>${value}</strong><small>${label}</small></div></div>`}
function tabs(active){return `<nav class="tabbar" aria-label="App navigation">${[['kitchen','plate','Kitchen'],['pantry','shelf','Pantry'],['reports','report','Journal'],['settings','settings','Settings']].map(([id,ic,label])=>`<button data-route="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${label}</button>`).join('')}</nav>`}
function heading(eyebrow,title,detail){return `<div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${detail?`<p>${detail}</p>`:''}`}
function intentionNoun(){return state.intention==='Read more'?'reading':state.intention==='Time with people'?'connection':'creating'}
function nextOpeningMinutes(){let [h,m]=state.opening.split(':').map(Number);let delta=h*60+m-(9*60+41);return delta>0?delta:delta+1440}
function timeLabel(t){let [h,m]=t.split(':').map(Number);return `${h%12||12}${m?':'+String(m).padStart(2,'0'):''}${h>=12?'pm':'am'}`}
const ingredientGroups=[
 {id:'carbs',name:'Carbs',amount:'Small daily portions',why:'Quick hits of entertainment keep you coming back for one more scroll.',examples:'Feeds · reels · quick checks',rule:'A shared daily limit',ids:[0,1,3],color:'#e5b18c'},
 {id:'fats',name:'Fats',amount:'Occasional treats',why:'Shows and games are enjoyable, but one sitting can fill your whole evening.',examples:'Streaming · games · movie nights',rule:'Within kitchen hours',ids:[4,2],color:'#d3c19b'},
 {id:'protein',name:'Protein',amount:'More purposeful time',why:'These apps help you learn, create, connect, or get something done.',examples:'Reading · learning · useful tools',rule:'Always available',ids:[8,10,11],color:'#bdcd94'}
];
function ingredientArt(g,hero=false){return `<div class="ingredient-plate ${hero?'hero-plate':''}" style="view-transition-name:plate-${g.id}"><div class="ingredient-plate-inner">${g.ids.map((i,j)=>`<span class="ingredient-bit" style="--app-color:${apps[i].color};--i:${j};view-transition-name:app-${g.id}-${i}">${appLogo(apps[i])}</span>`).join('')}</div></div>`}
function ingredientHero(g){return `<section class="ingredient-hero" style="--group-accent:${g.color}" aria-label="${g.name} explained"><div class="hero-counter"><div class="hero-cutlery" aria-hidden="true"></div>${ingredientArt(g,true)}<span class="hero-food-label">${g.examples}</span></div><div class="ingredient-overlay"><span class="hero-kicker">${g.amount}</span><h2 style="view-transition-name:title-${g.id}">${g.name}</h2><p>${g.why}</p><span class="hero-rule">${icon(g.id==='protein'?'leaf':g.id==='fats'?'clock':'plate')}${g.rule}</span></div></section>`}
function ingredientRow(g){return `<div class="ingredient-list-row" style="--group-accent:${g.color}">${ingredientArt(g)}<div><h3 style="view-transition-name:title-${g.id}">${g.name}</h3><b>${g.amount}</b><p>${g.rule}</p></div>${icon('check')}</div>`}
function changeIngredientStep(step){if(ingredientAnimating)return;ingredientAnimating=true;const update=()=>{ingredientStep=step;render()};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.body.classList.contains('paused')){const transition=document.startViewTransition(update);transition.finished.catch(()=>{}).finally(()=>ingredientAnimating=false)}else{update();ingredientAnimating=false}}
function build(){let content='',footer=primary('Continue'),main=false;let s=state;
 switch(route){
 case 'welcome':content=scene('prep')+heading('Welcome to ScreenDiet','Your apps.<br>Your plate.<br><em>Your balance.</em>','A kitchen for your digital life. Choose what you consume, when you consume it, and how much feels right.');footer=primary('Prepare my digital diet')+'<div class="small">A little preparation. More room for life.</div>';break;
 case 'story':content=storyIllustration('overflow')+heading('A healthier relationship','You don’t need to<br>quit every treat.','Some apps nourish you. Some are an occasional indulgence. The trouble starts when the kitchen never closes.')+'<div class="note">ScreenDiet helps you choose a rhythm, without treating every app the same.</div>';footer=primary('Let’s find my balance');break;
 case 'groups':{
 const g=ingredientGroups[ingredientStep];
 content=`<div class="ingredient-story"><div class="row"><div class="eyebrow">Meet your ingredients</div><div class="ingredient-dots" aria-label="${ingredientStep<3?'Food group '+(ingredientStep+1)+' of 3':'All food groups introduced'}">${ingredientGroups.map((_,i)=>`<i class="${i<=ingredientStep?'active':''}"></i>`).join('')}</div></div>${g?ingredientHero(g):heading('Your ingredients, together','A place for every app.','Small portions. Occasional treats. More purposeful time.')}<div class="ingredient-recap ${g?'':'complete'}" aria-label="Your ingredient list">${ingredientGroups.slice(0,ingredientStep).map(ingredientRow).join('')}</div>${ingredientStep===3?'<p class="ingredient-footnote">You decide each app’s place by how you use it.</p>':''}</div>`;
 footer=primary(ingredientStep<2?'Next · '+ingredientGroups[ingredientStep+1].name:ingredientStep===2?'See my ingredients':'Find my balance',ingredientStep<3?'ingredient-next':'next');break;
 }
 case 'goal':content=heading('Your reason to begin','What would a little<br>balance give you?','Your diet should support the life you want to live.')+choice('Be more present','Less autopilot. More moments that count.','goal','Be more present','heart')+choice('Find my focus','Space to settle into meaningful work.','goal','Find my focus','hourglass')+choice('Sleep more peacefully','Let the day end without one more scroll.','goal','Sleep more peacefully','moon');break;
 case 'intention':content=storyIllustration('life')+heading('Make room for something','What belongs on<br>the other side of less?','Choose one thing you’d like to have more time for.')+choice('Read more','A few pages instead of another feed.','intention','Read more','book')+choice('Time with people','Attention for the people around you.','intention','Time with people','heart')+choice('Make something','More space to create and explore.','intention','Make something','spark');break;
 case 'habits':content=heading('No judgment. Just a starting point.','What does your<br>usual day look like?','Your estimate helps us suggest a starting recipe.')+'<div class="section-label">Daily screen time · your estimate</div>'+['Under 2 hours','2–4 hours','4–6 hours','Over 6 hours'].map(t=>choice(t,'','hours',t,'clock')).join('')+'<div class="section-label">When is it hardest to stop?</div>'+['First thing in the morning','Between tasks','Late at night'].map(t=>choice(t,'','struggle',t,'moon')).join('');break;
 case 'permission':content=storyIllustration('connect')+heading('Connect your ingredients','Your kitchen needs<br>to know your apps.','Screen Time permission lets ScreenDiet apply your chosen limits and show Apple’s activity reports.')+'<div class="card">'+benefit('shield','Private by design','Your app selections and diet stay on your device.')+benefit('lock','You choose the ingredients','Select apps with Apple’s secure picker.')+'</div><div class="note">Prototype only. The iPhone app will show Apple’s authorization dialog here.</div>';footer=primary('Preview permission step','permission');break;
 case 'carbs':case 'fats':case 'protein':{
 let g=route;let copy={carbs:['Build your Carbs plate','The apps you snack on.','Add the apps where a quick check becomes a long scroll. These share your daily portion.'],fats:['Build your Fats plate','A little indulgence.<br>With a little intention.','Choose apps you enjoy occasionally. These follow your kitchen hours.'],protein:['Build your Protein plate','Keep the good<br>stuff on the table.','Choose useful apps you want to keep available. Protein is not blocked by your diet.']}[g];content=heading(g==='carbs'?'Daily portion':g==='fats'?'During kitchen hours':'Always available','Your '+g.charAt(0).toUpperCase()+g.slice(1)+' plate.',g==='carbs'?'Choose the apps you snack on.':g==='fats'?'Choose your occasional indulgences.':'Choose the apps that nourish your day.')+plate(g)+`<div class="plate-meta" id="plate-count">${s.selections[g].length} apps on your ${g} plate · tap an icon to remove</div><div class="row"><div class="section-label" style="margin:10px 0">Ingredient tray</div><button class="state-button" data-action="clear-plate">Clear plate</button></div><div class="tray">${apps.map(a=>`<button class="ingredient" data-app="${a.id}" aria-pressed="${s.selections[g].includes(a.id)}" style="--app-color:${a.color}"><span class="mini-icon">${appLogo(a)}</span>${a.name}</button>`).join('')}</div><div class="small selection-note">Swipe the tray for more apps · Apple’s picker on iPhone</div>`;footer=primary(`Serve my ${g} plate`);break;}
 case 'insight':content=heading('A little perspective','Small portions.<br>A meaningful difference.','Imagine trimming 30 minutes from a daily scrolling habit.')+'<div class="recipe"><div class="eyebrow">A possible return</div><h3>3½ hours a week.</h3><p>That’s space for a chapter, a conversation, or something you’ve been putting off.</p><div class="recipe-line"><span>Make room for</span><b>'+s.intention+'</b></div><span class="recipe-stamp">YOUR TIME, WELL SPENT</span></div><div class="note">Illustrative calculation: 30 minutes × 7 days. This is a scenario, not measured usage or a promised result.</div>';footer=primary('Prepare my recipe');break;
 case 'plan':content=heading('Choose your recipe','A rhythm you can<br>actually stick with.','Start gently. You can adjust your diet later.')+choice('Gentle','90 min of Carbs · a softer starting point','plan','Gentle','leaf')+choice('Balanced','45 min of Carbs · room for treats and focus','plan','Balanced','plate')+choice('Focused','30 min of Carbs · a more deliberate rhythm','plan','Focused','hourglass')+'<div class="note">Suggested starting point: Balanced. No shame if Gentle fits you better.</div>';break;
 case 'portion':content=heading('Plate a little more deliberately','How much feels<br>like enough?','Choose a daily Carbs portion shared across your selected apps.')+`<div class="dial" id="portion-dial"><div class="dial-core"><strong id="portion-big">${s.portion} min</strong><span>YOUR DAILY SERVING</span></div></div><label class="field-label" for="portion"><span>Daily portion</span><b id="portion-value">${s.portion} min</b></label><input id="portion" type="range" min="15" max="120" step="5" value="${s.portion}"><div class="row small"><span>A smaller serving</span><span>A gentler start</span></div><div class="card">${benefit('plate','One plate, shared across Carbs',s.selections.carbs.length+' selected apps share this allowance. Fats follow kitchen hours; Protein stays available.')}</div>`;break;
 case 'schedule':content=heading('Give your day some rhythm','A kitchen with<br>opening hours.','Choose when Carbs and Fats are available. Protein stays on the table.')+`<div class="dial" id="window-dial"><div class="dial-core"><strong id="window-big">${timeLabel(s.opening)} — ${timeLabel(s.closing)}</strong><span>KITCHEN HOURS</span></div><span class="clock-dot"></span></div><div class="times"><label for="opening">Kitchen opens<input type="time" id="opening" value="${s.opening}" step="900"></label><label for="closing">Kitchen closes<input type="time" id="closing" value="${s.closing}" step="900"></label></div><div class="note">Choose an overnight window if that fits your day. Outside this window, your selected Carbs and Fats are blocked.</div>`;break;
 case 'night':content=featureIllustration('night')+heading('Let the kitchen rest','The best midnight<br>snack might be sleep.','An optional Night Fast gives your selected Carbs and Fats a quiet stretch overnight.')+`<div class="card"><div class="settings-row"><span>Night Fast · 10pm–7am</span><button class="toggle" role="switch" aria-label="Night Fast" aria-checked="${s.night}" data-toggle="night"></button></div><p style="margin:8px 0 0;font-size:10px">Protein remains available. Night Fast takes priority over kitchen hours.</p></div><div class="small">Premium feature in the iPhone app. This prototype lets you explore it.</div>`;break;
 case 'notifications':content=featureIllustration('reminders')+heading('A gentle nudge','A helpful reminder.<br>Never a lecture.','Know when your kitchen opens, when your portion is nearly served, and when it’s time to rest.')+`<div class="card"><div class="row"><div class="icon-wrap">${icon('bell')}</div><div><h3>Your kitchen is open</h3><p style="margin:0;font-size:10px">A fresh portion. A new day.</p></div></div></div><div class="card"><div class="settings-row"><span>Gentle reminders</span><button class="toggle" role="switch" aria-label="Gentle reminders" aria-checked="${s.notifications}" data-toggle="notifications"></button></div></div><div class="note">iOS notification permission will be requested on your phone.</div>`;break;
 case 'review':content=heading('Prepared just for you','Your recipe for<br>a little more '+(s.intention==='Read more'?'reading.':s.intention==='Time with people'?'connection.':'creating.'),'Your ingredients. Your portions. Your rhythm.')+recipe()+`<button class="secondary" data-route="carbs">Adjust my ingredients</button>`;footer=primary('Looks like my kind of diet');break;
 case 'paywall':content=`<div class="paywall">${plate('carbs',true)}${heading('Your complete kitchen','Make room for<br>'+intentionNoun()+'.','Your recipe is ready. Give yourself more ways to keep it balanced.')}${benefit('moon','A quiet kitchen at night','Protect your evenings with Night Fast.')}${benefit('ticket','Room for an extra serving','More flexibility when life happens.')}${benefit('report','See your diet take shape','Detailed reports and weekly balance.')}${choice('Annual membership','Sample price · billed yearly','billing','year','leaf').replace('</span><span class="check">','</span><div class="plan-price">$29.99<small>per year · sample</small></div><span class="check">')}${choice('Monthly membership','Sample price · billed monthly','billing','month','clock').replace('</span><span class="check">','</span><div class="plan-price">$4.99<small>per month · sample</small></div><span class="check">')}<div class="small">Design prices only. No trial is promised. Final prices and eligible offers come from the App Store.</div><button class="state-button" data-action="purchase-error">Preview unavailable state</button></div>`;footer=primary('Preview membership','subscribe')+'<button class="text-btn" data-action="free">Continue with Free</button><div class="row small"><button class="state-button" data-action="restore">Restore purchases</button><button class="state-button" data-action="terms">Subscription details</button></div>';break;
 case 'activation':content=`<div class="success-mark">${icon('check')}</div>`+featureIllustration('served')+heading('Prepared. Balanced. Yours.','Your digital diet<br>is ready to serve.','Start small. Follow your rhythm. Make room for '+intentionNoun()+'.')+`<div class="mini-plates"><i>${icon('plate')}</i><i>${icon('ticket')}</i><i>${icon('leaf')}</i></div><div class="note">Prototype complete. No restrictions have been activated.</div>`;footer=primary('Step into my kitchen','finish');break;
 case 'kitchen':{
 main=true;let st=s.kitchen,info={open:['Your kitchen is open.','A fresh portion. Enjoy it with intention.'],closed:['Closed for a little balance.','Your kitchen opens at '+timeLabel(s.opening)+'. Protein stays available.'],night:['Let the kitchen rest.','Night Fast until 7am. Leave room for sleep.'],focus:['Something good is cooking.','Your '+s.duration+'-minute Focus Fast is active.'],portion:['Your portion is served.','Carbs return tomorrow. Fats follow kitchen hours.'],cheat:['A little extra serving.','Your cheat meal opens Carbs for 15 minutes.']}[st];content=`<div class="kitchen-header"><div><div class="eyebrow">Friday, October 9 · sample day</div><h2>Your Kitchen</h2></div><span class="tag">${s.plan.toUpperCase()}</span></div><div class="status-switch" aria-label="Preview kitchen state">${['open','closed','night','focus','portion'].map(t=>`<button class="${st===t?'active':''}" data-state="${t}">${t==='portion'?'Portion used':t.charAt(0).toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="hero-state">${scene(['night','focus','closed'].includes(st)?st:'open')}<span class="tag">${st==='open'?'NOW SERVING':st==='cheat'?'EXTRA SERVING':'KITCHEN AT REST'}</span><h3>${info[0]}</h3><p>${info[1]}</p></div><div class="card row"><div><div class="eyebrow">Your Carbs portion</div><h3 style="margin-top:8px">A little room left.</h3><div class="small">13 of ${s.portion} min served · sample</div></div>${ring(st==='portion'?'0':Math.max(0,s.portion-13))}</div><div class="stat-grid"><div class="card">${icon('leaf')}<b>5 days</b><small>of showing up · sample</small></div><div class="card">${icon('ticket')}<b>${s.cheats} left</b><small>extra servings this week</small></div></div><div class="actions"><button class="action" data-route="focus">${icon('hourglass')}<b>Focus Fast</b><small>Close for a little while</small></button><button class="action" data-route="cheat">${icon('ticket')}<b>Cheat meal</b><small>A little flexibility</small></button></div>${['focus','cheat'].includes(st)?'<button class="secondary" data-action="end-fast">Return to my rhythm</button>':''}<div class="section-label">Your recipe today</div><div class="row small"><span>${timeLabel(s.opening)} — ${timeLabel(s.closing)}</span><button class="state-button" data-route="schedule">Adjust hours</button></div>`;footer=tabs(route);break;}
 case 'pantry':main=true;content=heading('Good ingredients. Your choices.','Your Pantry','Everything has a place. Edit your plates as your habits change.')+['carbs','fats','protein'].map(g=>`<div class="shelf"><div class="shelf-content">${plate(g,true)}<div><h3>${g.charAt(0).toUpperCase()+g.slice(1)}</h3><p>${g==='carbs'?'Portioned daily':g==='fats'?'During kitchen hours':'Always on the table'}<br>${s.selections[g].length} selected apps</p><button class="secondary" data-route="${g}">Edit plate ${icon('arrow')}</button></div></div></div>`).join('')+'<div class="note">Apps not on these plates remain unrestricted. In the iPhone app, categories and websites can also be selected.</div>';footer=tabs(route);break;
 case 'reports':main=true;content=heading('Your nutrition journal','Balance, over time.','Progress is a pattern, not a perfect day.')+`<div class="group-tabs report-tabs"><button data-report="today" class="${s.report==='today'?'active':''}">Today</button><button data-report="week" class="${s.report==='week'?'active':''}">Last 7 days</button></div><div id="report-content">${reportContent()}</div><div class="row"><button class="state-button" data-action="report-loading">Preview loading</button><button class="state-button" data-action="report-empty">Preview empty</button><button class="state-button" data-action="report-error">Preview error</button></div><div class="note">All numbers are sample data. On iPhone, exact activity is rendered inside Apple’s report extension.</div>`;footer=tabs(route);break;
 case 'focus':content=featureIllustration('focus')+heading('Close the kitchen. Open some space.','What could you do<br>with a little focus?','Carbs and Fats take a break. Protein stays available.')+choice('One focused hour','A small pocket of protected attention.','duration',60,'hourglass')+choice('Two hours of space','Settle into something meaningful.','duration',120,'hourglass')+choice('Until the next opening',Math.floor(nextOpeningMinutes()/60)+'h '+nextOpeningMinutes()%60+'m · based on the sample 9:41am clock','duration',nextOpeningMinutes(),'sun');footer=`<div class="slider-confirm"><span>Slide to close the kitchen</span><div class="slider-knob">${icon('arrow')}</div><input type="range" min="0" max="100" value="0" id="confirm-slide" aria-label="Slide to start Focus Fast"></div><button class="text-btn" data-action="start-focus">Or tap to confirm Focus Fast</button>`;break;
 case 'cheat':content=featureIllustration('extra')+heading('Flexibility belongs in a balanced diet','A little treat.<br>Then back to your rhythm.','A cheat meal opens your selected Carbs for 15 minutes. Your schedule takes over afterward.')+`<div class="stat-grid"><div class="card"><b>${s.cheats}</b><small>left this week</small></div><div class="card"><b>15 min</b><small>per extra serving</small></div></div>${['night','focus'].includes(s.kitchen)?'<div class="note">Let your fast finish first. Cheat meals can’t lift a Night Fast or Focus Fast.</div>':''}${s.kitchen==='cheat'?'<div class="note">Your cheat meal is already active. No extra serving will be used.</div>':''}`;footer=['night','focus','cheat'].includes(s.kitchen)?primary('Back to my kitchen','finish'):s.cheats?'<button class="primary hold" id="hold"><span>Hold to serve my cheat meal</span></button><div class="small">Hold for 2 seconds · keyboard: Enter to confirm</div>':primary('Explore more flexibility','paywall');break;
 case 'settings':main=true;content=heading('A kitchen that fits your life','Your rhythm','Adjust the recipe as you go.')+`<div class="card"><div class="settings-row"><span>Recipe</span><button class="state-button" data-route="plan">${s.plan} →</button></div><div class="settings-row"><span>Daily Carbs portion</span><button class="state-button" data-route="portion">${s.portion} min →</button></div><div class="settings-row"><span>Kitchen hours</span><button class="state-button" data-route="schedule">${timeLabel(s.opening)}–${timeLabel(s.closing)} →</button></div><div class="settings-row"><span>Night Fast</span><button class="toggle" role="switch" aria-label="Night Fast" aria-checked="${s.night}" data-toggle="night"></button></div></div><div class="section-label">Gentle support</div><div class="card"><div class="settings-row"><span>Notifications</span><button class="toggle" role="switch" aria-label="Notifications" aria-checked="${s.notifications}" data-toggle="notifications"></button></div><div class="settings-row"><span>Membership</span><button class="state-button" data-route="paywall">${s.premium?'Preview member':'Explore'} →</button></div><div class="settings-row"><span>App selection</span><button class="state-button" data-route="pantry">Your Pantry →</button></div></div><div class="note">This review changes only the HTML prototype. Your iPhone app and saved diet are untouched.</div><button class="secondary" data-route="welcome">Replay the kitchen story</button>`;footer=tabs(route);break;
 }
 return {content,footer,main};
}
function benefit(ic,t,d){return `<div class="benefit">${icon(ic)}<div>${t}<small>${d}</small></div></div>`}
function recipe(){return `<div class="recipe"><div class="eyebrow">ScreenDiet · Your personal recipe</div><h3>The ${state.plan} Diet</h3><p>Prepared for ${state.goal.toLowerCase()}.</p>${[['Carbs',`${state.selections.carbs.length} apps · ${state.portion} min daily`],['Fats',`${state.selections.fats.length} apps · kitchen hours`],['Protein',`${state.selections.protein.length} apps · always available`],['Kitchen opens',timeLabel(state.opening)],['Kitchen closes',timeLabel(state.closing)],['Night Fast',state.night?'10pm–7am':'Not added']].map(([k,v])=>`<div class="recipe-line"><span>${k}</span><b>${v}</b></div>`).join('')}<span class="recipe-stamp">PREPARED WITH INTENTION</span></div>`}
function reportContent(){let week=state.report==='week';return `<div class="journal-head row">${ring('B+','BALANCE · SAMPLE',43)}<div><div class="eyebrow" style="color:#6c825a">A little more balanced</div><h3 style="font-size:18px;margin-top:8px">Room for the<br>good stuff.</h3><div class="small">${week?'Your week':'Today'}, thoughtfully served.</div></div></div><div class="row"><h3>${week?'Your week at a glance':'Today’s servings'}</h3><span class="tag">SAMPLE DATA</span></div>${week?`<div class="bars">${[65,48,76,55,40,34,45].map((v,i)=>`<div class="bar-col"><div class="bar"><span style="--value:${v}%;--i:${i}"></span></div><small>${['S','S','M','T','W','T','F'][i]}</small></div>`).join('')}</div><div class="legend"><span><i></i>Daily Carbs consumption</span><span>Lower portions ≠ less total activity</span></div>`:''}<div class="card"><h3>What was on your plate?</h3>${[['Carbs',week?'3h 45m':'32 min',46],['Fats',week?'2h 20m':'24 min',29],['Protein',week?'2h 10m':'18 min',25]].map(([t,v,p])=>`<div class="nutrition-line"><span>${t}</span><div class="meter"><span style="width:${p*2}%"></span></div><b>${v}</b></div>`).join('')}</div><div class="stat-grid"><div class="card">${icon('moon')}<b>${week?'42':'8'} min</b><small>after 10pm · sample</small></div><div class="card">${icon('clock')}<b>${week?'186':'29'}</b><small>pickups · sample</small></div></div><div class="section-label">Most served · sample</div>${[['Instagram','1h 42m'],['YouTube','1h 15m'],['Books','58 min']].map(([n,t])=>`<div class="settings-row"><span>${n}</span><span>${t}</span></div>`).join('')}`}
function render(){let idx=onboarding.findIndex(x=>x[0]===route),{content,footer,main}=build();$('#screen-name').textContent=all.find(x=>x[0]===route)[1];$('#navigator').innerHTML='<div class="group">PREPARE YOUR DIET</div>'+onboarding.map(([id,n],i)=>navButton(id,n,String(i+1).padStart(2,'0'))).join('')+'<div class="group">LIVE WITH YOUR RHYTHM</div>'+mainScreens.map(([id,n])=>navButton(id,n,'↗')).join('');$('#app').innerHTML=`${main?'<div class="top"><span class="wordmark">screendiet.</span><span class="eyebrow">YOUR DIGITAL KITCHEN</span></div>':`<div class="top"><button class="icon-btn" data-action="back" aria-label="Go back">${icon('back')}</button><span class="wordmark">screendiet.</span><span class="step">${idx>=0?String(idx+1).padStart(2,'0')+' / '+onboarding.length:'YOUR KITCHEN'}</span></div>${idx>=0?`<div class="progress">${onboarding.map((_,i)=>`<i class="${i<=idx?'done':''}"></i>`).join('')}</div>`:''}`}<div class="scroll screen-enter">${content}</div>${main?footer:`<div class="footer">${editingReturn&&['carbs','fats','protein','plan','portion','schedule'].includes(route)?primary('Save my recipe'):footer}</div>`}`;$('#hint').textContent=['carbs','fats','protein'].includes(route)?'Tap apps in the ingredient tray. Watch them land on your plate.':'Explore the story, or jump between screens using the navigator.';if(route==='activation'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)celebrate();updateDial();}
function navButton(id,n,num){return `<button data-route="${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span>${num}</span>${n}</button>`}
function celebrate(){for(let i=0;i<16;i++){let el=document.createElement('i');el.className='confetti';el.style.cssText=`--cx:${(Math.random()-.5)*320}px;--cy:${-70+Math.random()*220}px;background:${i%2?'#e5b18c':'#bdcd94'};animation-delay:${i*.02}s`;$('#app').append(el);setTimeout(()=>el.remove(),2000)}}
function updateDial(){if($('#portion-dial'))$('#portion-dial').style.background=`conic-gradient(from 180deg,var(--sage) 0deg ${state.portion/120*360}deg,#ffffff0a ${state.portion/120*360}deg)`;if($('#window-dial')){let toM=t=>Number(t.slice(0,2))*60+Number(t.slice(3)),open=toM(state.opening),closed=toM(state.closing);let span=(closed-open+1440)%1440;$('#window-dial').style.background=`conic-gradient(from ${open/1440*360}deg,var(--sage) 0deg ${span/1440*360}deg,#ffffff0a ${span/1440*360}deg)`;$('#window-big').textContent=timeLabel(state.opening)+' — '+timeLabel(state.closing)}}
function addApp(id){let g=state.group;let existing=Object.keys(state.selections).find(k=>state.selections[k].includes(id));if(existing===g){removeApp(id);return}if(existing){state.selections[existing]=state.selections[existing].filter(x=>x!==id);toast(apps.find(x=>x.id===id).name+' moved from '+existing+' to '+g)}state.selections[g].push(id);refreshPlate(id);}
function refreshPlate(newId){const p=$('#live-plate');if(!p)return;let old=new Map([...p.querySelectorAll('.app-token')].map(el=>[el.dataset.remove,el]));let ids=state.selections[state.group],pos=positions(ids.length);p.querySelector('.plate-empty')?.remove();ids.forEach((id,i)=>{let token=old.get(id);if(token){token.style.setProperty('--x',pos[i][0]+'px');token.style.setProperty('--y',pos[i][1]+'px')}else{let a=apps.find(x=>x.id===id);let el=document.createElement('button');el.className='app-token land';el.dataset.remove=id;el.title='Remove '+a.name;el.setAttribute('aria-label','Remove '+a.name+' from '+state.group);el.style.cssText=`--x:${pos[i][0]}px;--y:${pos[i][1]}px;--app-color:${a.color}`;el.innerHTML=appLogo(a);p.append(el);setTimeout(()=>el.classList.remove('land'),700)}});if(!ids.length)p.insertAdjacentHTML('beforeend',`<div class="plate-empty">${icon('plate')}Your plate is ready.<br>Add your first app.</div>`);$('#plate-count').textContent=ids.length+' apps on your '+state.group+' plate · tap an icon to remove';document.querySelectorAll('[data-app]').forEach(el=>el.setAttribute('aria-pressed',ids.includes(el.dataset.app)));}
function removeApp(id){if(!['carbs','fats','protein'].includes(route)){toast('Edit this plate in your Pantry.');return}state.selections[state.group]=state.selections[state.group].filter(x=>x!==id);let el=document.querySelector(`.plate [data-remove="${id}"]`);if(el){el.classList.add('leaving');setTimeout(()=>el.remove(),220)}refreshPlate();}
function startFocus(){state.kitchen='focus';navigate('kitchen');toast('Prototype: Focus Fast started. No apps are blocked.');}
function cheat(){if(state.cheats<=0||['night','focus','cheat'].includes(state.kitchen))return;state.cheats--;state.kitchen='cheat';navigate('kitchen');toast('Prototype: one extra serving used.');}
function action(a){switch(a){case 'ingredient-next':changeIngredientStep(Math.min(3,ingredientStep+1));break;case 'next':if(editingReturn){let target=editingReturn;editingReturn=null;toast('Your sample recipe is updated.');navigate(target)}else next();break;case 'back':{if(route==='groups'&&ingredientStep>0){changeIngredientStep(ingredientStep-1);break}if(editingReturn){let target=editingReturn;editingReturn=null;navigate(target);break}let idx=onboarding.findIndex(x=>x[0]===route);navigate(idx>0?onboarding[idx-1][0]:'kitchen');break}case 'permission':toast('Permission preview complete. No device access requested.');next();break;case 'subscribe':state.premium=true;toast('Membership preview only. No payment taken.');{let target=editingReturn||'activation';editingReturn=null;navigate(target)}break;case 'free':state.premium=false;{let target=editingReturn||'activation';editingReturn=null;navigate(target)}break;case 'finish':navigate('kitchen');break;case 'paywall':navigate('paywall');break;case 'start-focus':startFocus();break;case 'end-fast':state.kitchen='open';render();toast('Returned to your kitchen rhythm.');break;case 'clear-plate':state.selections[state.group].slice().forEach(removeApp);break;case 'restore':toast('Prototype: no purchases to restore.');break;case 'terms':toast('Sample subscriptions renew until canceled. Actual terms will use App Store products.');break;case 'purchase-error':toast('Membership unavailable. Try again later or continue with Free.');break;case 'report-loading':$('#report-content').innerHTML='<div class="loading" role="status" aria-label="Loading report"></div><p class="center">Preparing your journal…</p>';reportLoadTimer=setTimeout(()=>{if(route==='reports')$('#report-content').innerHTML=reportContent()},1800);break;case 'report-empty':$('#report-content').innerHTML=`<div class="card center">${icon('report')}<h3 style="margin-top:12px">A fresh page.</h3><p>Your journal will grow as activity becomes available.</p><button class="secondary" data-action="report-retry">Show sample report</button></div>`;break;case 'report-error':$('#report-content').innerHTML='<div class="card"><h3>Your journal needs a moment.</h3><p>The report couldn’t load. Your diet settings are still here.</p><button class="secondary" data-action="report-retry">Try again</button></div>';break;case 'report-retry':$('#report-content').innerHTML=reportContent();break;}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.route){if(['pantry','settings','kitchen'].includes(route)&&['carbs','fats','protein','plan','portion','schedule','paywall'].includes(b.dataset.route))editingReturn=route;else editingReturn=null;navigate(b.dataset.route);return}if(b.dataset.choice){let key=b.dataset.choice;state[key]=key==='duration'?Number(b.dataset.value):b.dataset.value;if(key==='plan')state.portion={Gentle:90,Balanced:45,Focused:30}[state.plan];let scroll=$('.scroll').scrollTop;render();$('.scroll').scrollTop=scroll;return}if(b.dataset.toggle){state[b.dataset.toggle]=!state[b.dataset.toggle];b.setAttribute('aria-checked',state[b.dataset.toggle]);return}if(b.dataset.app){addApp(b.dataset.app);return}if(b.dataset.remove){removeApp(b.dataset.remove);return}if(b.dataset.state){state.kitchen=b.dataset.state;render();return}if(b.dataset.report){state.report=b.dataset.report;render();return}if(b.dataset.action)action(b.dataset.action);});
document.addEventListener('input',e=>{if(e.target.id==='portion'){state.portion=Number(e.target.value);$('#portion-big').textContent=state.portion+' min';$('#portion-value').textContent=state.portion+' min';updateDial()}if(['opening','closing'].includes(e.target.id)){if(e.target.value)state[e.target.id]=e.target.value;updateDial()}if(e.target.id==='confirm-slide'){let v=Number(e.target.value);$('.slider-confirm').style.setProperty('--slide',v/100*($('.slider-confirm').clientWidth-56)+'px');if(v>=97)startFocus()}});
document.addEventListener('change',e=>{if(e.target.id==='confirm-slide'&&Number(e.target.value)<97){e.target.value=0;$('.slider-confirm').style.setProperty('--slide','0px')}});
document.addEventListener('pointerdown',e=>{let b=e.target.closest('#hold');if(!b)return;b.setPointerCapture(e.pointerId);holdStart=performance.now();clearInterval(holdTimer);holdTimer=setInterval(()=>{let progress=Math.min(1,(performance.now()-holdStart)/2000);b.style.setProperty('--held',progress);if(progress>=1){clearInterval(holdTimer);cheat()}},30)});
function stopHold(){clearInterval(holdTimer);$('#hold')?.style.setProperty('--held',0)}document.addEventListener('pointerup',stopHold);document.addEventListener('pointercancel',stopHold);document.addEventListener('keydown',e=>{if(e.target.id==='hold'&&['Enter',' '].includes(e.key)){e.preventDefault();if(confirm('Use one sample cheat meal for 15 minutes?'))cheat()}});
$('#motion').addEventListener('click',()=>{let paused=document.body.classList.toggle('paused');$('#motion').setAttribute('aria-pressed',paused);$('#motion').textContent=paused?'Resume motion':'Pause motion';});$('#reset').addEventListener('click',()=>{state=defaultState();ingredientStep=0;editingReturn=null;navigate('welcome');toast('Your sample recipe is reset.');});window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'welcome');
